const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // The Alisal Fire occurred in Santa Barbara County, California.
  // This ROI is centered on the approximate location of the fire.
  const roi = ee.Geometry.Rectangle([-120.45, 34.45, -119.95, 34.65]);

  // The MODIS MCD64A1 product is monthly, so we select the month of the fire.
  const startDate = ee.Date('2021-10-01');
  const endDate = ee.Date('2021-10-31');

  // Question-specific dates to filter the 'BurnDate' band.
  // The 'BurnDate' band stores the day of the year (Julian day).
  const startDay = ee.Date('2021-10-11').getRelative('day', 'year');
  const endDay = ee.Date('2021-10-13').getRelative('day', 'year');

  // 2. Data Acquisition & Check
  const modisBurn = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterDate(startDate, endDate)
    .filterBounds(roi);

  const imageCount = modisBurn.size().getInfo();
  if (imageCount === 0) {
    console.log("Evidence: No MODIS burn area images found for October 2021 in the specified region.");
    console.log("C1");
    return;
  }
  // We expect one monthly composite image.
  const image = modisBurn.first();
  const burnDate = image.select('BurnDate');

  // 3. Processing
  // Create a mask for pixels that burned within the specified 3-day window.
  const fireMask = burnDate.gte(startDay).and(burnDate.lte(endDay));
  const fireImage = image.updateMask(fireMask);

  // Calculate the area of the masked pixels.
  // ee.Image.pixelArea() creates an image where each pixel's value is its area in square meters.
  // We multiply by the fire mask to get the area of only the burned pixels.
  const pixelArea = ee.Image.pixelArea().updateMask(fireMask);

  // 4. Calculation
  const stats = pixelArea.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 500, // MODIS native resolution for this product
    maxPixels: 1e9
  });

  const burnedAreaSqM = stats.get('area');

  // Check if the calculation returned a result.
  if (burnedAreaSqM.getInfo() === null) {
    console.log("Evidence: Calculation resulted in null. This might be due to no valid pixels after masking.");
    const validPixelCheck = fireMask.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: 500,
        maxPixels: 1e9
    }).get('BurnDate').getInfo();
    if(validPixelCheck === 0) {
        console.log("Reason: No pixels corresponding to the specified burn dates were found in the ROI.");
        console.log("C2");
    } else {
        console.log("Reason: Unknown calculation failure.");
        console.log("C3");
    }
    return;
  }

  // Convert area from square meters to acres (1 acre = 4046.86 sq m).
  const burnedAreaAcres = ee.Number(burnedAreaSqM).divide(4046.86);
  const finalAreaAcres = burnedAreaAcres.getInfo();

  // 5. Validation & Final Answer
  console.log(`MODIS Images Found: ${imageCount}`);
  console.log(`Start Julian Day: ${startDay.getInfo()}`);
  console.log(`End Julian Day: ${endDay.getInfo()}`);
  console.log(`Calculated Burned Area (Oct 11-13): ${finalAreaAcres.toFixed(2)} acres`);

  const thresholdAcres = 10000;
  if (finalAreaAcres < thresholdAcres) {
    console.log(`Result (${finalAreaAcres.toFixed(2)}) is less than the threshold (${thresholdAcres} acres).`);
    console.log("A");
  } else {
    console.log(`Result (${finalAreaAcres.toFixed(2)}) is not less than the threshold (${thresholdAcres} acres).`);
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log("D");
});
